contract CryptoBuiltinsProbe {
    bytes32 public kPacked;
    bytes32 public kEncoded;
    bytes32 public sPacked;
    bytes20 public rPacked;
    address public rec27;
    address public rec0;

    event Ran(bytes20 ripe, address rec27, address rec0);

    function run() public {
        kPacked = keccak256(abi.encodePacked(uint8(255), uint16(513), uint64(0xdeadbeef), uint256(1)));
        kEncoded = keccak256(abi.encode(uint8(255), uint16(513), uint64(0xdeadbeef), uint256(1)));
        sPacked = sha256(abi.encodePacked(uint8(255), uint16(513), uint64(0xdeadbeef), uint256(1)));
        rPacked = ripemd160(abi.encodePacked(uint8(255), uint16(513), uint64(0xdeadbeef), uint256(1)));
        rec27 = ecrecover(kEncoded, 27, bytes32(uint256(1)), bytes32(uint256(1)));
        rec0 = ecrecover(kEncoded, 0, bytes32(uint256(1)), bytes32(uint256(1)));
        emit Ran(rPacked, rec27, rec0);
    }
}

