contract EnvProbe {
    uint256 public gasSeen;
    uint256 public numberSeen;

    function snapshot() public {
        uint256 n = block.number;
        numberSeen = n;
        gasSeen = gasleft() + 1000;
    }

    function getGas() public view returns (uint256) {
        return gasleft();
    }

    function gasDelta() public view returns (uint256) {
        uint256 g0 = gasleft();
        uint256 s = 0;
        for (uint256 i = 0; i < 5; i++) {
            s += i * 3;
        }
        return g0 - gasleft() + s;
    }
}

