contract ValueForward {
    uint256 public totalReceived;
    uint256 public withdrawn;

    event Received(address indexed from, uint256 value);
    event Sent(address indexed to, uint256 value);
    event Detailed(address indexed from, uint256 value, bytes32 ref);

    receive() external payable {
        totalReceived += msg.value;
        emit Received(msg.sender, msg.value);
    }

    function depositRef(bytes32 ref) external payable returns (uint256) {
        totalReceived += msg.value;
        emit Detailed(msg.sender, msg.value, ref);
        return address(this).balance;
    }

    function withdraw(uint256 amount) external {
        require(amount <= address(this).balance, "insufficient");
        (bool ok, ) = payable(msg.sender).call{value: amount}("");
        require(ok, "send-failed");
        withdrawn += amount;
        emit Sent(msg.sender, amount);
    }
}

